// whether the band shows one row instead of all of them; kept in $.store too, so a new session starts folded
const isCollapsed = atom({ plugin: 'plan-progress', key: 'collapsed' } as const, false)
const COLLAPSED_STORE_KEY = 'collapsed'
const setCollapsed = async ($: EngineInterface, collapsed: boolean) => {
  await update($, isCollapsed, () => collapsed)
  await $.store.set(COLLAPSED_STORE_KEY, collapsed)
}
// the fold button: ⌃ folds the band to nothing but ⌄ and the number of rows hidden, which opens it again. On the desktop ⌃ sits
// at the middle of the band's top edge, one row up out of the tree; a terminal has no room above, so there it takes a
// column left of the gear
const FOLD_CELLS = 5
const FOLD_UP = '⌃'
const FOLD_DOWN = '⌄'
// the pane that lists every style with a live preview; opened from the ⚙ beside the Progress button
const STYLE_PANE = 'plan-progress-styles'
const STYLE_PANE_TITLE = '進度條樣式'

// what the footer's gear does: it opens the style pane, where the bars are also shown or hidden
async function openStyles($: EngineInterface) {
  return $.ui.open({ id: STYLE_PANE, title: STYLE_PANE_TITLE })
}
// the gear that opens the pane; U+FE0E asks for the plain text glyph, not the colour emoji
const SETTINGS_GLYPH = '⚙︎'
// the column the gear takes at the band's right, in cells
const GEAR_CELLS = 3

// how subagent strips show under a bar: one strip each, one summary line, or none
const AGENT_VIEWS = ['expanded', 'summary', 'hidden'] as const
type AgentView = (typeof AGENT_VIEWS)[number]
const AGENT_VIEW_LABEL: Record<AgentView, string> = { expanded: '展開', summary: '摘要', hidden: '隱藏' }
const isAgentView = (v: unknown): v is AgentView => typeof v === 'string' && (AGENT_VIEWS as readonly string[]).includes(v)
const agentView = atom({ plugin: 'plan-progress', key: 'agentView' } as const, 'expanded' as string)
const AGENT_VIEW_STORE_KEY = 'agentView'
const agentViewOf = async ($: EngineInterface): Promise<AgentView> => {
  const v = await read($, agentView)
  return isAgentView(v) ? v : 'expanded'
}
const setAgentView = async ($: EngineInterface, v: AgentView) => {
  await update($, agentView, () => v)
  await $.store.set(AGENT_VIEW_STORE_KEY, v)
}
// the colour the bars run in, one of ACCENT_IDS, or '' for each style's own; the drawing module holds it too
const accentChoice = atom({ plugin: 'plan-progress', key: 'accent' } as const, '' as string)
const ACCENT_STORE_KEY = 'accent'
const setAccentChoice = async ($: EngineInterface, v: string) => {
  setAccent(v)
  await update($, accentChoice, () => v)
  await $.store.set(ACCENT_STORE_KEY, v)
}
const STRIP_H = 18
const STRIP_GAP = 3
const MAX_STRIPS = 4 // past this, the finished ones fold into one "+N more" strip
const FOLD_MS = 5000 // finished strips stay this long, failed ones stay until the bar closes

const STATE_COLOR: Record<PlanState, string> = { running: '#8B7CF6', needs_input: '#E09A1E', error: '#E5484D', done: '#30A46C' }
const STATE_GLYPH: Record<PlanState, string> = { running: '●', needs_input: '?', error: '!', done: '✓' }
const STATUSES: StepStatus[] = ['pending', 'active', 'done', 'error', 'skipped']
const TRACK_H = 22
const NARROW = 360

const RULES = `# Progress bars
Tasks needing more than ~3 edits or commands get a bar via ${TOOL}: create it once with the full breakdown (2-7 stages with short steps, or kind "todo" for one flat list; titles of at most 4 words; the bar title and step titles in the user's language, stage names always in English), then update it with short calls only: {id, next:true} when the active step is finished, or {id, done:[...], active:"..."}, {id, failed:"...", note}. Send state "needs_input" with a note before asking the user to decide. Never describe the bars to the user.`

type Raw = Record<string, unknown>
const str = (v: unknown, max = 120) => (typeof v === 'string' ? v.replace(/\s+/g, ' ').trim().slice(0, max) : '')
// a message as a person reads it: the app wraps pasted text and slash commands in tags (<pasted_content id="…">,
// <command-name>/handoff</command-name>), which made a session's row read "<pasted_content id="5589"> 0x…".
// Pasted text becomes （貼上的內容）, a command its name, and any other tag goes
const readable = (v: unknown, max = 60) => {
  if (typeof v !== 'string') return ''
  const t = v
    .replace(/<pasted_content\b[^>]*>[\s\S]*?(<\/pasted_content>|$)/g, ' （貼上的內容） ')
    .replace(/<command-name>\s*([^<]*?)\s*<\/command-name>/g, ' $1 ')
    .replace(/<command-(message|args)>[\s\S]*?(<\/command-\1>|$)/g, ' ')
    .replace(/<\/?[a-zA-Z][\w-]*(\s[^<>]*)?>?/g, ' ')
  return str(t, max)
}
const status = (v: unknown): StepStatus => (STATUSES.includes(v as StepStatus) ? (v as StepStatus) : 'pending')
const list = (v: unknown): Raw[] => (Array.isArray(v) ? v.filter(x => x && typeof x === 'object') : []) as Raw[]
const isFinished = (s: StepStatus) => s === 'done' || s === 'skipped'

const same = (a: string, b: string) => a.trim().toLowerCase() === b.trim().toLowerCase()

// short updates: {next:true}, {done:[titles]}, {active:title}, {failed:title} against the stored plan
function applyOps(stages: PlanStage[], input: Raw): PlanStage[] {
  const next = stages.map(s => ({ ...s, steps: s.steps.map(st => ({ ...st })) }))
  const steps = next.flatMap(s => s.steps)
  const find = (title: string) => steps.find(st => same(st.title, title))
  if (input.next === true) {
    const at = steps.findIndex(st => st.status === 'active') >= 0 ? steps.findIndex(st => st.status === 'active') : steps.findIndex(st => !isFinished(st.status))
    const cur = steps[at]
    if (cur) cur.status = 'done'
    const following = steps.slice(at + 1).find(st => st.status === 'pending')
    if (following) following.status = 'active'
  }
  for (const t of Array.isArray(input.done) ? input.done : []) {
    const st = typeof t === 'string' ? find(t) : undefined
    if (st) st.status = 'done'
  }
  const active = typeof input.active === 'string' ? find(input.active) : undefined
  if (active) {
    const at = steps.indexOf(active)
    steps.forEach((st, i) => {
      if (st.status === 'active' && i !== at) st.status = i < at ? 'done' : 'pending'
    })
    active.status = 'active'
  }
  const failed = typeof input.failed === 'string' ? find(input.failed) : undefined
  if (failed) failed.status = 'error'

  return next
}

function normalize(input: Raw, prev: Plan | null, now: number, id: string): Plan {
  const isPartial = list(input.stages).length === 0 && prev !== null
  const stages: PlanStage[] = isPartial ? applyOps(prev.stages, input) : list(input.stages)
    .map(s => ({
      name: str(s.name, 80) || 'Stage',
      steps: list(s.steps).map(st => ({
        title: str(st.title) || 'Step',
        status: status(st.status),
        substeps: list(st.substeps).map(sub => ({ title: str(sub.title) || '…', status: status(sub.status) })),
      })),
    }))
    .filter(s => s.steps.length > 0) as PlanStage[]
  const title = str(input.title, 80) || prev?.title || 'Plan'
  const steps = stages.flatMap(s => s.steps)
  const isAllDone = steps.length > 0 && steps.every(s => isFinished(s.status))
  const asked = input.state as PlanState
  const failedNow = typeof input.failed === 'string'
  const state: PlanState = ['running', 'needs_input', 'error', 'done'].includes(asked) ? asked : isAllDone ? 'done' : failedNow ? 'error' : 'running'

  return {
    id,
    title,
    kind: input.kind === 'todo' || (isPartial && prev?.kind === 'todo') ? 'todo' : 'plan',
    stages,
    state,
    note: str(input.note, 160) || null,
    startedAt: prev && prev.title === title ? prev.startedAt : now,
  }
}

const clean = (s: string) =>
  s
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/[*_`]/g, '')
    .replace(/^\s*(\d+[.)]|[-*+]|\[[ xX]\])\s+/, '')
    .replace(/^(\d+[.)]|\[[ xX]\])\s+/, '')
    .trim()

function parsePlan(markdown: string, now: number): Plan | null {
  let title = ''
  const headed: PlanStage[] = []
  const items: { depth: number; text: string }[] = []
  for (const line of markdown.split(/\r?\n/)) {
    const h = line.match(/^(#{1,4})\s+(.*)$/)
    if (h) {
      const text = clean(h[2] ?? '')
      if (h[1] === '#' && !title) title = text
      else headed.push({ name: text, steps: [] })
      continue
    }
    const li = line.match(/^(\s*)(\d+[.)]|[-*+])\s+(.*)$/)
    if (!li) continue
    const depth = Math.floor((li[1] ?? '').replace(/\t/g, '  ').length / 2)
    const text = clean(li[3] ?? '').slice(0, 120)
    if (!text) continue
    items.push({ depth, text })
    const stage = headed[headed.length - 1]
    if (!stage) continue
    const step = stage.steps[stage.steps.length - 1]
    if (depth === 0 || !step) stage.steps.push({ title: text, status: 'pending', substeps: [] })
    else step.substeps.push({ title: text, status: 'pending' })
  }
  let stages = headed.filter(s => s.steps.length > 0)
  if (stages.length === 0) {
    if (items.some(i => i.depth > 0)) {
      for (const item of items) {
        const stage = stages[stages.length - 1]
        if (item.depth === 0 || !stage) stages.push({ name: item.text, steps: [] })
        else stage.steps.push({ title: item.text, status: 'pending', substeps: [] })
      }
      stages = stages.map(s => (s.steps.length ? s : { ...s, steps: [{ title: s.name, status: 'pending', substeps: [] }] }))
    } else if (items.length > 0) {
      stages = [{ name: 'Tasks', steps: items.map(i => ({ title: i.text, status: 'pending' as StepStatus, substeps: [] })) }]
    }
  }
  if (stages.length === 0) return null
  const first = stages[0]?.steps[0]
  if (first) first.status = 'active'

  return { id: 'plan', title: title || 'Plan', kind: stages.length === 1 ? 'todo' : 'plan', stages, state: 'running', note: null, startedAt: now }
}

function st(title: string, s: StepStatus): PlanStep {
  return { title, status: s, substeps: [] }
}

const DEMO = (now: number): Plan => ({
  id: 'demo',
  title: 'Orders module',
  kind: 'plan',
  state: 'running',
  note: null,
  startedAt: now - 260_000,
  stages: [
    { name: 'Analysis', steps: [st('Read modules', 'done'), st('Find dependencies', 'done'), st('List changes', 'done')] },
    { name: 'DB migration', steps: [st('Table schema', 'done'), st('Create migration', 'done'), st('Move data', 'active'), st('Indexes', 'pending')] },
    { name: 'API', steps: [st('Endpoints', 'pending'), st('Validation', 'pending'), st('Access rules', 'pending')] },
    { name: 'Interface', steps: [st('List page', 'pending'), st('Order card', 'pending'), st('Filters', 'pending'), st('Empty states', 'pending')] },
    { name: 'Verify', steps: [st('Tests', 'pending'), st('Build', 'pending')] },
  ],
})

// ---------- drawing ----------

// the current step is the one marked active (or failed), since Claude may leave a step for later; pos counts the
// finished steps, at is the current step's place (the same rule as where() in styles.ts)
type Where = { pos: number; at: number; total: number; stage: number; step: number; stageSize: number }

function where(p: Plan): Where {
  const steps = p.stages.flatMap((s, i) => s.steps.map((step, j) => ({ i, j, step })))
  const live = steps.findIndex(x => x.step.status === 'active' || x.step.status === 'error')
  const first = steps.findIndex(x => !isFinished(x.step.status))
  const isDone = p.state === 'done' || first < 0
  const at = isDone ? steps.length : live >= 0 ? live : first
  const pos = isDone ? steps.length : steps.filter(x => isFinished(x.step.status)).length
  const cur = steps[Math.min(at, steps.length - 1)]
  const stage = cur?.i ?? 0

  return { pos, at, total: steps.length, stage, step: at >= steps.length ? (p.stages[stage]?.steps.length ?? 0) : (cur?.j ?? 0) + 1, stageSize: p.stages[stage]?.steps.length ?? 0 }
}

const hex = (h: string) => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16))
const mix = (a: number[], b: number[], m: number) => a.map((v, i) => Math.round(v + ((b[i] ?? 0) - v) * m))
const rgb = (c: number[]) => `rgb(${c.join(',')})`
const esc = (s: string) => s.replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c] ?? c)
const hash = (a: number, b: number, k: number) => {
  const x = Math.sin(a * 127.1 + b * 311.7 + k * 74.7) * 43758.5453
  return x - Math.floor(x)
}
const textWidth = (s: string, px = 6.7) => [...s].reduce((w, ch) => w + (/[　-鿿]/.test(ch) ? 12 : /[ilI.,:;'|!]/.test(ch) ? 3.4 : /[mwMWШЩЖМ]/.test(ch) ? 9.5 : px), 0)

const ICON_PATH: Partial<Record<PlanState, string>> = {
  needs_input: 'M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3M12 17h.01',
  error: 'M18 6 6 18M6 6l12 12',
  done: 'M20 6 9 17l-5-5',
}

// last drawn head position per plan, so a redraw glides from where the bar was
const lastHead = new Map<string, number>()

function trackSvg(p: Plan, W: number): string {
  const H = TRACK_H
  const w = where(p)
  const done = p.state === 'done'
  // the fill is exactly the finished share: a fresh plan starts empty
  const frac = done ? 1 : Math.min(1, w.pos / Math.max(1, w.total))
  const fx = frac * W
  const key = p.id
  const from = lastHead.get(key) ?? fx
  lastHead.set(key, fx)

  const acc = hex(STATE_COLOR[p.state])
  const light = mix(acc, [255, 255, 255], 0.32)
  const grey = [132, 130, 138]
  const ease = 'calcMode="spline" keyTimes="0;1" keySplines=".2 .8 .2 1"'
  const glide = Math.abs(from - fx) > 0.5

  const bounds: number[] = []
  let acc2 = 0
  p.stages.forEach((s, i) => {
    acc2 += s.steps.length
    if (i < p.stages.length - 1) bounds.push((acc2 / w.total) * W)
  })

  // pixels: 3px grid, 7 rows, denser and closer to the state colour towards the head
  const buckets = [0, 1, 2, 3, 4].map(b => {
    const m = b / 4
    const dense = done ? 0.8 : 0.22 + 0.78 * Math.pow(m, 1.5)
    return { color: rgb(done ? light : mix(grey, light, m)), opacity: (0.35 + 0.65 * dense).toFixed(2) }
  })
  let px = ''
  for (let col = 0; col * 3 < fx; col++) {
    const x = col * 3
    const u = Math.min(1, (x + 1.5) / fx)
    const dense = done ? 0.8 : 0.22 + 0.78 * Math.pow(u, 1.5)
    const bucket = done ? 4 : Math.min(4, Math.floor(Math.min(1, Math.pow(u, 0.9) * 1.1) * 4.99))
    for (let r = 0; r < 7; r++) {
      if (hash(col, r, 1) > dense + 0.1) continue
      px += `<rect x="${x}" y="${1 + r * 3}" class="b${bucket} t${Math.floor(hash(col, r, 2) * 4)}"/>`
    }
  }

  let marks = ''
  let k = 0
  p.stages.forEach((s, i) => {
    s.steps.forEach((_, j) => {
      if (k > 0) {
        const x = (k / w.total) * W
        const isStage = j === 0
        // stage boundaries are full-height lines, steps are short ticks; bright once passed
        const passed = x < fx - 1
        const h = isStage ? H : 8
        const fill = passed ? rgb(mix(light, [255, 255, 255], 0.45)) : '#8A8984'
        const opacity = passed ? (isStage ? 0.95 : 0.6) : isStage ? 0.7 : 0.45
        marks += `<rect x="${(x - (isStage ? 1 : 0.75)).toFixed(1)}" y="${(H - h) / 2}" width="${isStage ? 2 : 1.5}" height="${h}" rx=".75" fill="${fill}" opacity="${opacity}"/>`
      }
      k++
    })
    void i
  })

  // knob: a pill with stage and count, or a round dot with the stage number when narrow
  const isNarrow = W < NARROW
  const color = STATE_COLOR[p.state]
  const icon = ICON_PATH[p.state]
  const single = p.stages.length === 1
  const number = single ? Math.min(w.total, w.at + 1) : w.stage + 1
  let knob = ''
  let kw = H
  if (isNarrow) {
    const label = done ? '' : String(number)
    knob = `<circle cx="0" cy="${H / 2}" r="${H / 2}" fill="${color}"/>${
      done ? `<path d="${ICON_PATH.done}" transform="translate(-6 5) scale(.5)" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>` : `<text x="0" y="${H / 2 + 4.2}" text-anchor="middle" class="kt">${label}</text>`
    }`
  } else {
    const name = done ? 'Done' : single ? (p.stages[0]?.name ?? 'Tasks') : (p.stages[w.stage]?.name ?? '')
    const agents = p.agents ?? []
    const base = p.id === AGENTS ? `${w.pos}/${w.total}` : done ? `${w.total}/${w.total}` : single ? `${number}/${w.total}` : `${w.step}/${w.stageSize}`
    const agentCount = agents.length > 0 && p.id !== AGENTS ? ` · ${agents.filter(a => a.state === 'done').length}/${agents.length} agents` : ''
    const count = base + agentCount
    const iconW = icon ? 16 : 0
    const countW = textWidth(count, 6.5)
    const maxW = Math.max(80, W * 0.55)
    let shown = name
    while (shown.length > 3 && 20 + iconW + textWidth(shown) + 6 + countW > maxW) shown = shown.slice(0, -1)
    if (shown !== name) shown = shown.trimEnd() + '…'
    kw = Math.round(20 + iconW + textWidth(shown) + 6 + countW)
    const left = -kw / 2 + 10
    knob = `<rect x="${-kw / 2}" y="0" width="${kw}" height="${H}" rx="${H / 2}" fill="${color}"/>`
    if (icon) knob += `<path d="${icon}" transform="translate(${left} 5) scale(.5)" fill="none" stroke="#fff" stroke-width="3.6" stroke-linecap="round" stroke-linejoin="round"/>`
    knob += `<text x="${left + iconW}" y="${H / 2 + 4.2}" class="kt">${esc(shown)}<tspan class="kc" dx="6">${count}</tspan></text>`
  }
  const clampX = (x: number) => Math.max(kw / 2, Math.min(W - kw / 2, x))
  const kx = clampX(fx)
  const kFrom = clampX(from)

  const style = `<style>
.b0{fill:${buckets[0]?.color};fill-opacity:${buckets[0]?.opacity}}.b1{fill:${buckets[1]?.color};fill-opacity:${buckets[1]?.opacity}}
.b2{fill:${buckets[2]?.color};fill-opacity:${buckets[2]?.opacity}}.b3{fill:${buckets[3]?.color};fill-opacity:${buckets[3]?.opacity}}
.b4{fill:${buckets[4]?.color};fill-opacity:${buckets[4]?.opacity}}
rect[class]{width:2px;height:2px}
.t0,.t1,.t2,.t3{animation:tw ${done ? 3.2 : 2.2}s ease-in-out infinite}
.t1{animation-duration:${done ? 3.8 : 2.8}s;animation-delay:-.7s}.t2{animation-duration:${done ? 4.4 : 1.9}s;animation-delay:-1.3s}.t3{animation-duration:${done ? 3.5 : 3.3}s;animation-delay:-.4s}
@keyframes tw{0%,100%{opacity:1}50%{opacity:${done ? 0.8 : 0.45}}}
.kt{font:500 12px 'Anthropic Sans',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;fill:#fff}
.kc{font-weight:400;fill-opacity:.75}
@media (prefers-reduced-motion:reduce){.t0,.t1,.t2,.t3{animation:none}}
</style>`
  const glideFill = glide ? `<animate attributeName="width" from="${from.toFixed(1)}" to="${fx.toFixed(1)}" dur=".45s" ${ease} fill="freeze"/>` : ''
  const glideKnob = glide ? `<animateTransform attributeName="transform" type="translate" from="${kFrom.toFixed(1)} 0" to="${kx.toFixed(1)} 0" dur=".45s" ${ease} fill="freeze"/>` : ''

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${style}
<defs><clipPath id="pill"><rect width="${W}" height="${H}" rx="${H / 2}"/></clipPath><clipPath id="fill"><rect width="${fx.toFixed(1)}" height="${H}">${glideFill}</rect></clipPath>
<linearGradient id="base" x1="0" x2="${fx.toFixed(1)}" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="${rgb(acc)}" stop-opacity="${done ? 0.3 : 0.05}"/><stop offset="1" stop-color="${rgb(acc)}" stop-opacity=".33"/></linearGradient></defs>
<g clip-path="url(#pill)"><rect width="${W}" height="${H}" fill="#808080" fill-opacity=".16"/>
<g clip-path="url(#fill)"><rect width="${fx.toFixed(1)}" height="${H}" fill="url(#base)"/>${px}</g>${marks}</g>
<g transform="translate(${kx.toFixed(1)} 0)">${glideKnob}${knob}</g></svg>`
}

const AGENT_COLOR: Record<AgentRun['state'], string> = {
  running: STATE_COLOR.running,
  waiting: STATE_COLOR.needs_input,
  done: STATE_COLOR.done,
  error: STATE_COLOR.error,
}

const elapsed = (ms: number) => {
  const sec = Math.max(0, Math.round(ms / 1000))
  return sec < 60 ? `${sec}s` : `${Math.floor(sec / 60)}m ${sec % 60}s`
}

// which strips show: all of a small batch; in a big one the unfinished first, the rest folded into one line
function visibleAgents(p: Plan, now: number): { shown: AgentRun[]; hidden: AgentRun[] } | null {
  const list = p.agents ?? []
  if (list.length === 0) return null
  const hasError = list.some(a => a.state === 'error')
  if (p.agentsDoneAt && now - p.agentsDoneAt > FOLD_MS && !hasError) return null
  if (list.length <= MAX_STRIPS) return { shown: list, hidden: [] }
  const keep = new Set(list.filter(a => a.state !== 'done').slice(0, MAX_STRIPS - 1).map(a => a.id))
  for (const a of [...list].reverse()) {
    if (keep.size >= MAX_STRIPS - 1) break
    keep.add(a.id)
  }
  return { shown: list.filter(a => keep.has(a.id)), hidden: list.filter(a => !keep.has(a.id)) }
}

// the person's choice applied to the strips: summary folds them into one made-up run that every style draws as a strip
function applyAgentView(v: { shown: AgentRun[]; hidden: AgentRun[] } | null, view: AgentView): { shown: AgentRun[]; hidden: AgentRun[] } | null {
  if (!v || view === 'expanded') return v
  if (view === 'hidden') return null
  const all = [...v.shown, ...v.hidden]
  const count = (s: AgentRun['state']) => all.filter(a => a.state === s).length
  const tool = (
    [
      ['running', 'running'],
      ['waiting', 'waiting'],
      ['done', 'done'],
      ['error', 'failed'],
    ] as const
  )
    .map(([s, label]) => (count(s) ? `${count(s)} ${label}` : ''))
    .filter(Boolean)
    .join(' · ')
  const state: AgentRun['state'] = count('waiting') ? 'waiting' : count('running') ? 'running' : count('error') ? 'error' : 'done'
  const ends = all.map(a => a.endedAt)
  const endedAt = ends.every((t): t is number => t !== null) ? Math.max(...ends) : null
  const startedAt = Math.min(...all.map(a => a.startedAt))
  return { shown: [{ id: 'agents-summary', title: plural(all.length, 'subagent'), state, tool, startedAt, endedAt, depth: 0 }], hidden: [] }
}

// what each strip showed last time it was drawn, so a change morphs from the old status instead of jumping
const lastStrip = new Map<string, { tool: string; color: string }>()
const MORPH = '.2s'

const stripsHeight = (n: number) => n * STRIP_H + (n - 1) * STRIP_GAP

// one tinted strip per agent: state colour, name, what it does now and for how long; not a progress bar
function stripsSvg(v: { shown: AgentRun[]; hidden: AgentRun[] }, W: number, now: number): string {
  const isNarrow = W < NARROW
  const rows: string[] = []
  v.shown.forEach((a, i) => {
    const c = AGENT_COLOR[a.state]
    const y = i * (STRIP_H + STRIP_GAP)
    const indent = a.depth > 0 ? 12 : 0
    let px = ''
    if (a.state === 'running') {
      for (let col = 0; col * 3 < W; col++) {
        for (let r = 0; r < 4; r++) {
          if (hash(col + i * 41, r, 5) > 0.2) continue
          px += `<rect x="${col * 3}" y="${y + 3 + r * 3.6}" class="t${Math.floor(hash(col, r, 6) * 4)}" fill="${c}" fill-opacity=".32"/>`
        }
      }
    }
    const nameRoom = isNarrow ? W - 30 - indent : W * 0.5
    let name = (a.depth > 0 ? '↳ ' : '') + a.title
    while (name.length > 4 && textWidth(name, 6.2) > nameRoom) name = name.slice(0, -1)
    if (name !== (a.depth > 0 ? '↳ ' : '') + a.title) name = name.trimEnd() + '…'
    const nameX = 19 + indent
    const toolX = nameX + textWidth(name, 6.2) + 8
    const time = elapsed((a.endedAt ?? now) - a.startedAt)
    // a status change: the old word blurs out while the new one blurs in, and the tint flows to the new colour
    const was = lastStrip.get(a.id)
    lastStrip.set(a.id, { tool: a.tool, color: c })
    const isToolChanged = was !== undefined && was.tool !== a.tool
    const flow = (attr: string) => (was && was.color !== c ? `<animate attributeName="${attr}" from="${was.color}" to="${c}" dur="${MORPH}" fill="freeze"/>` : '')
    const tool = isNarrow
      ? ''
      : (isToolChanged ? `<text x="${toolX}" y="${y + 12.5}" class="sn mo" style="fill:${was.color}">${esc(was.tool)}</text>` : '') +
        `<text x="${toolX}" y="${y + 12.5}" class="sn${isToolChanged ? ' mi' : ''}" style="fill:${c}">${esc(a.tool)}</text>` +
        `<text x="${W - 9}" y="${y + 12.5}" text-anchor="end" class="sn st">${time}</text>`
    rows.push(
      `<rect x="0" y="${y}" width="${W}" height="${STRIP_H}" rx="${STRIP_H / 2}" fill="${c}" fill-opacity=".15">${flow('fill')}</rect>${px}` +
        `<circle cx="${10 + indent}" cy="${y + STRIP_H / 2}" r="3" fill="${c}"${a.state === 'running' ? ' class="sd"' : ''}>${flow('fill')}</circle>` +
        `<text x="${nameX}" y="${y + 12.5}" class="sn">${esc(name)}</text>` +
        tool,
    )
  })
  if (v.hidden.length > 0) {
    const y = v.shown.length * (STRIP_H + STRIP_GAP)
    const doneCount = v.hidden.filter(a => a.state === 'done').length
    rows.push(
      `<rect x="0" y="${y}" width="${W}" height="${STRIP_H}" rx="${STRIP_H / 2}" fill="#808080" fill-opacity=".14"/>` +
        `<text x="10" y="${y + 12.5}" class="sn st">+${plural(v.hidden.length, 'more agent')} · ${doneCount} done</text>`,
    )
  }
  return `<style>.sn{font:400 11.5px 'Anthropic Sans',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;fill:#1F1E1C}.st{fill-opacity:.65}
@media (prefers-color-scheme:dark){.sn{fill:#F0EEFC}}
.sd{animation:sp 1.1s ease-in-out infinite}@keyframes sp{50%{opacity:.3}}
.mi{animation:mi ${MORPH} ease-out both}@keyframes mi{from{opacity:0;filter:blur(3px)}}
.mo{animation:mo ${MORPH} ease-in both}@keyframes mo{to{opacity:0;filter:blur(3px)}}
@media (prefers-reduced-motion:reduce){.sd,.mi,.mo{animation:none}.mo{opacity:0}}</style>${rows.join('')}`
}

function plural(n: number, word: string) {
  return `${n} ${word}${n === 1 ? '' : 's'}`
}

// the state glyph left of a title, drawn in a box of one width with its mark at the middle: as letters, ● ? ! ✓
// are each a different width, so the titles after them did not start at one place
const GLYPH_W = 12
// what a glyph says to a reader that cannot see it; a desktop draws no Svg whose alt is empty (0.5.41-0.5.49 drew the
// glyphs and the colour dots with none, and they did not show)
const GLYPH_WORD: Record<string, string> = { '●': '進行中', '?': '等你決定', '!': '出錯', '✓': '完成' }
const GLYPH_H = 16
function glyphSvg(char: string, color: string, isDim = false) {
  const c = GLYPH_W / 2
  const mark =
    char === '●'
      ? `<circle cx="${c}" cy="${GLYPH_H / 2}" r="4.5" fill="${color}"/>`
      : char === '✓'
        ? `<path d="M${c - 4} ${GLYPH_H / 2}l2.8 2.9 5.2-5.6" fill="none" stroke="${color}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>`
        : `<text x="${c}" y="${GLYPH_H / 2 + 4.5}" text-anchor="middle" style="font:700 13px 'Anthropic Sans',ui-sans-serif,system-ui,-apple-system,sans-serif" fill="${color}">${esc(char)}</text>`
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${GLYPH_W}" height="${GLYPH_H}" viewBox="0 0 ${GLYPH_W} ${GLYPH_H}"${isDim ? ' opacity=".45"' : ''}>${mark}</svg>`
}

// another session's state in words, for a row with no bar: left-aligned in the bar's own width, in the bars' note type (12 px, regular, muted)
const statusSvg = (word: string, W: number) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${TRACK_H}" viewBox="0 0 ${W} ${TRACK_H}"><style>.w{font:400 12px 'Anthropic Sans',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;fill:#73726C}@media (prefers-color-scheme:dark){.w{fill:#A3A19A}}</style><text x="0" y="${TRACK_H / 2 + 4.5}" class="w">${esc(word)}</text></svg>`

// what another session's main loop is doing, from the tool it runs now; an MCP tool goes by its server's name
function toolLabel(tool?: string) {
  if (!tool) return '處理中'
  const mcp = /^mcp__(.+?)__/.exec(tool)
  if (mcp) return `外部工具 · ${mcp[1]}`
  const word: Record<string, string> = {
    Bash: '執行指令', PowerShell: '執行指令', Read: '讀檔案', Edit: '改檔案', Write: '改檔案', MultiEdit: '改檔案', NotebookEdit: '改檔案',
    Grep: '找檔案', Glob: '找檔案', Agent: '派 subagent', Task: '派 subagent', WebFetch: '查網路', WebSearch: '查網路', Skill: '用技能',
  }
  return word[tool] ? `${word[tool]} · ${tool}` : tool
}

// a session that runs with no bar: a short track with a segment sweeping across it in the style's running colour, then what
// it does now, about where the other bars' notes start;
// the source stays the same while the label does, so a redraw does not restart the sweep
function runningSvg(label: string, W: number, color: string) {
  const trackW = Math.round(Math.min(110, W * 0.4))
  const seg = Math.round(trackW * 0.3)
  const y = TRACK_H / 2 - 2
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${TRACK_H}" viewBox="0 0 ${W} ${TRACK_H}"><style>.t{fill:#E2E0DA}.w{font:400 12px 'Anthropic Sans',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;fill:#73726C}.sweep{animation:sw 1.4s ease-in-out infinite}@keyframes sw{from{transform:translateX(-${seg}px)}to{transform:translateX(${trackW}px)}}@media (prefers-color-scheme:dark){.t{fill:#3A3A38}.w{fill:#A3A19A}}@media (prefers-reduced-motion:reduce){.sweep{animation:none;transform:translateX(${Math.round((trackW - seg) / 2)}px)}}</style><clipPath id="c"><rect y="${y}" width="${trackW}" height="4" rx="2"/></clipPath><rect class="t" y="${y}" width="${trackW}" height="4" rx="2"/><g clip-path="url(#c)"><rect class="sweep" y="${y}" width="${seg}" height="4" rx="2" fill="${color}"/></g><text x="${trackW + 12}" y="${TRACK_H / 2 + 4.5}" class="w">${esc(label)}</text></svg>`
}

// a drawing placed in a fixed-height slot (centred or at the top), so previews of different heights take the same room
function inSlot(drawn: { svg: string; height: number }, W: number, slotH: number, align: 'center' | 'top'): { svg: string; height: number } {
  const dy = align === 'center' ? Math.max(0, (slotH - drawn.height) / 2) : 0
  return {
    svg: `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${slotH}" viewBox="0 0 ${W} ${slotH}"><g transform="translate(0 ${dy})">${drawn.svg}</g></svg>`,
    height: slotH,
  }
}

// one bar with its strips in the chosen style; the bar above the prompt and the pane's previews both draw through here
function drawBar(style: StyleId, p: Plan, W: number, now: number, v: { shown: AgentRun[]; hidden: AgentRun[] } | null): { svg: string; height: number } {
  if (style !== 'original') return STYLES[style].draw(p, W, now, v)
  if (!v) return { svg: trackSvg(p, W), height: TRACK_H }
  const stripsH = 5 + stripsHeight(v.shown.length + (v.hidden.length > 0 ? 1 : 0))
  return {
    svg: `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${TRACK_H + stripsH}">${trackSvg(p, W)}<g transform="translate(0 ${TRACK_H + 5})">${stripsSvg(v, W, now)}</g></svg>`,
    height: TRACK_H + stripsH,
  }
}

// ---------- engine glue ----------

// a sound the mod raises on its own: silent while the person has turned sounds off
function play($: EngineInterface, name: 'decision' | 'error' | 'done') {
  void read($, soundsOn).then(isOn => (isOn ? playNow($, name) : undefined))
}
// the engine's player first (afplay on macOS); PowerShell where it cannot play
function playNow($: EngineInterface, name: 'decision' | 'error' | 'done') {
  const file = `${$.plugin.root}/sounds/${name}.wav`.replace(/\//g, '\\')
  void $.audio.play({ asset: `sounds/${name}.wav` }).catch(() =>
    $.process
      .run(['powershell', '-NoLogo', '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-Command', `(New-Object Media.SoundPlayer '${file}').PlaySync()`], { timeoutMs: 5000 })
      .catch(() => undefined),
  )
}

// the agents bar is the mod's own; the model never owes it an update
const AGENTS = 'agents:auto' // slug() never yields ':', so no model id can take it
const isOpenPlan = (p: Plan) => p.id !== AGENTS && p.state === 'running' && !p.isFinishing && !p.stages.flatMap(s => s.steps).every(s => isFinished(s.status))

const slug = (s: string) =>
  s
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 40) || 'plan'

// adds or replaces one bar by id; keeps at most MAX_BARS, dropping finished ones first
// computed inside update() from the latest list, so concurrent writers (parallel agents) do not drop each other
function placeBar(list: readonly Plan[], next: Plan): Plan[] {
  const prev = list.find(p => p.id === next.id)
  // an update keeps its row; a new bar goes to the bottom
  const rest = prev ? list.map(p => (p.id === next.id ? next : p)) : [...list, next]
  while (rest.length > MAX_BARS) {
    const doneAt = rest.findIndex(p => p.state === 'done')
    rest.splice(doneAt >= 0 ? doneAt : 0, 1)
  }
  return rest
}

// a main-loop turn is running: a done reached inside it sounds once the turn ends, after the reply is written
let isMainTurn = false
let owesDone = false

function chime($: EngineInterface, prev: PlanState | undefined, next: PlanState) {
  if (next === prev) return
  if (next === 'needs_input') play($, 'decision')
  if (next === 'error') play($, 'error')
  if (next === 'done') {
    if (isMainTurn) owesDone = true
    else play($, 'done')
  }
}

async function putPlan($: EngineInterface, next: Plan) {
  let prev: Plan | undefined
  await update($, plans, list => {
    prev = list.find(p => p.id === next.id)
    return placeBar(list, next)
  })
  chime($, prev?.state, next.state)
}

// ---------- agents: drawn from engine events alone, no model calls ----------
// each subagent lives on a bar as one state strip: the open task bar it was started under,
// the bar of its parent agent, or the mod's own "Agents" bar when no task is open.
// Module maps: a reload forgets running agents, whose strips then stay until the bar is closed.
const agentHome = new Map<string, string>() // agentId -> bar id
const toolUses = new Map<string, string>() // tool_use_id -> agentId, to find who waits on a permission
const waiting = new Set<string>()
let foldUntil = 0 // keep ticking until finished strips have folded

// the mod's own bar mirrors its agents as steps, finished first, so percent and count read done/total
function syncAuto(p: Plan, now: number): Plan {
  const agents = p.agents ?? []
  const isOver = agents.length > 0 && agents.every(a => a.state === 'done' || a.state === 'error')
  const agentsDoneAt = isOver ? (p.agentsDoneAt ?? now) : null
  if (p.id !== AGENTS) return { ...p, agentsDoneAt }
  const rank = (a: AgentRun) => (a.state === 'done' ? 0 : a.state === 'error' ? 1 : 2)
  const steps: PlanStep[] = [...agents]
    .sort((a, b) => rank(a) - rank(b))
    .map(a => ({ title: a.title, status: a.state === 'done' ? 'done' : a.state === 'error' ? 'error' : 'active', substeps: [] }))
  const state: PlanState = isOver
    ? agents.some(a => a.state === 'error') ? 'error' : 'done'
    : agents.some(a => a.state === 'waiting') ? 'needs_input' : 'running'
  return { ...p, agentsDoneAt, stages: [{ name: 'Agents', steps }], state }
}

function addRun(p: Plan, run: AgentRun, parentId: string | undefined, now: number): Plan {
  // a batch that has finished makes room for the next one
  const list = p.agentsDoneAt ? [] : [...(p.agents ?? [])]
  let at = list.length
  const parentAt = parentId ? list.findIndex(a => a.id === parentId) : -1
  if (parentAt >= 0) {
    at = parentAt + 1
    while (at < list.length && (list[at]?.depth ?? 0) > 0) at++
  }
  list.splice(at, 0, run)
  return syncAuto({ ...p, agents: list, agentsDoneAt: null }, now)
}

// changes one agent's strip inside the latest list; sounds follow the bar's state
async function editAgent($: EngineInterface, agentId: string, change: (a: AgentRun) => AgentRun) {
  const home = agentHome.get(agentId)
  if (!home) return
  const now = await $.clock.now()
  let before: PlanState | undefined
  let after: PlanState | undefined
  let isFolding = false
  await update($, plans, list =>
    list.map(p => {
      if (p.id !== home || !p.agents?.some(a => a.id === agentId)) return p
      before = p.state
      const next = syncAuto({ ...p, agents: p.agents.map(a => (a.id === agentId ? change(a) : a)) }, now)
      after = next.state
      isFolding = !p.agentsDoneAt && next.agentsDoneAt !== null
      return next
    }),
  )
  if (isFolding) foldUntil = now + FOLD_MS + 1500
  if (before !== undefined && after !== undefined) chime($, before, after)
}

async function dropPlan($: EngineInterface, id: string) {
  lastHead.delete(id)
  for (const p of await read($, plans)) if (p.id === id) for (const a of p.agents ?? []) lastStrip.delete(a.id)
  await update($, plans, list => list.filter(p => p.id !== id))
}

// finished bars stay until the person sends their next message (they have seen the result by then):
// they fade out for LEAVE_MS, then leave the list
const LEAVE_MS = 400
async function fadeOutDone($: EngineInterface) {
  const now = await $.clock.now()
  let isLeaving = false
  await update($, plans, list =>
    list.map(p => {
      if (p.state !== 'done' || p.leavingAt) return p
      isLeaving = true
      return { ...p, leavingAt: now }
    }),
  )
  if (isLeaving) $.clock.after(LEAVE_MS, () => dropLeft($))
}
async function dropLeft($: EngineInterface) {
  const now = await $.clock.now()
  for (const p of await read($, plans)) {
    if (!p.leavingAt || now - p.leavingAt < LEAVE_MS) continue
    lastHead.delete(p.id)
    for (const a of p.agents ?? []) lastStrip.delete(a.id)
  }
  await update($, plans, list => list.filter(p => !p.leavingAt || now - p.leavingAt < LEAVE_MS))
}
// a leaving bar's drawing fades to nothing; its title and count dim, since Text has no opacity
const fadeOut = (svg: string, W: number, H: number) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}"><style>@keyframes pp-leave{to{opacity:0}}.pp-leave{animation:pp-leave ${LEAVE_MS}ms ease-out forwards}</style><g class="pp-leave">${svg}</g></svg>`

// ---------- other sessions: each desktop session writes its status to a shared folder, every session reads the others ----------
type SessionStatus = 'working' | 'done' | 'needs_input' | 'idle' | 'ended'
type SessionFile = { v: 1; hostId: string; cwd: string; label: string; title?: string; tool?: string; state: SessionStatus; since: number; updatedAt: number; bars?: unknown[] }
const others = atom({ plugin: 'plan-progress', key: 'others' } as const, { rows: [] } as OthersView)
const crossOn = atom({ plugin: 'plan-progress', key: 'crossSessions' } as const, true)
const CROSS_STORE_KEY = 'crossSessions'
const setCross = async ($: EngineInterface, isOn: boolean) => {
  await update($, crossOn, () => isOn)
  await $.store.set(CROSS_STORE_KEY, isOn)
}
// the desktop's own session id; the link is built from it, never read from a file, since `open` acts on whatever it is given
const HOST_ID = /^local_[0-9a-f-]{36}$/
const linkOf = (hostId: string) => `claude://claude.ai/epitaxy/${hostId}`
// a session in a worktree (<project>/.claude/worktrees/<random name>) is named by its project, not the random folder
const projectOf = (cwd: string) => (cwd.includes('/.claude/worktrees/') ? cwd.split('/.claude/worktrees/')[0] : cwd).split('/').pop() ?? ''
const SEEN = 'seen.json'
const HEARTBEAT_MS = 30_000 // a working session rewrites its file this often
const WORKING_FRESH_MS = 90_000 // a working file older than this belongs to a session that is gone
const KEEP_MS = 24 * 3600_000 // a finished session older than this no longer shows
const MAX_OTHERS = 5
// every row's ✕ sits in a cell this wide, so a row without one keeps its bar in line
const CLOSE_CELLS = 3
// this session's own bars sit in a rounded frame when other sessions show under them: the frame's border and padding
// take about FRAME_PX across, and the rows under it are inset by FRAME_INSET cells so both groups line up
// (a terminal draws the border as a whole cell, so there the rows under it move in one cell more)
const FRAME_PX = 24
const FRAME_INSET = 1
// the space between the frame and the other sessions under it on the desktop, in px (a row's gap was too much)
const FRAME_GAP_PX = 2
// the space between rows on the desktop, in px: a row's gap (about 10 px) spread them out; no gap and this instead
const ROW_GAP_PX = 5
// the name on the frame's top line: its background is the desktop's grey band (measured in the light theme; the dark one
// is a guess), so the line does not show through the letters. The desktop places a Box one row up (top: -1) about
// FRAME_ROW_PX above the line (measured on a screenshot), so the drawing is two rows tall and the name sits at its middle
const FRAME_ROW_PX = 20
const FRAME_NAME_H = 2 * FRAME_ROW_PX
// the name starts where the rows' titles start, past the glyph's column: the titles start about this far right of where
// the name's drawing is placed (one cell in), measured on a screenshot; the line shows left of the name, its background
// only hides the line behind the letters
const FRAME_NAME_X = 27
function frameNameSvg(text: string) {
  // 10 px letters, smaller than the rows' titles; textWidth measures 12 px ones
  // a font with wider CJK letters than the estimate cut the name's end (seen in the promo's renderer), so leave room
  const textW = Math.round(((textWidth(text, 7.5) * 10) / 12) * 1.15)
  const width = FRAME_NAME_X + textW + 10
  // the line is hidden by a halo of the band's grey round the letters (a stroke painted under them), so the gap
  // fits the name as drawn on both sides; a background sized from the estimate left a wider gap on the right (0.5.62)
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${FRAME_NAME_H}" viewBox="0 0 ${width} ${FRAME_NAME_H}"><style>.w{font:500 10px 'Anthropic Sans',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;fill:#73726C;stroke:#F0F0F0;stroke-width:12px;stroke-linejoin:round;paint-order:stroke}@media (prefers-color-scheme:dark){.w{fill:#A3A19A;stroke:#2B2B29}}</style><text x="${FRAME_NAME_X}" y="${FRAME_ROW_PX + 3.5}" class="w">${esc(text)}</text></svg>`
  return { text, svg, width }
}
// the band's grey, painted as the fold button's own background so the frame's line has a gap there; the button is
// its content, drawn over it (a drawing of the grey placed beside the button hid it, 0.5.59-0.5.60). A Box takes one
// raw colour, so the theme setting picks it: the desktop's light grey, measured, and its dark one, a guess
const BAND_GREY = { light: '#F0F0F0', dark: '#2B2B29' }
// read from the theme setting when the session starts
let isDarkTheme = false
const POLL_EVERY = 2 // seconds between reads of the shared folder
let sessionsDir: string | null = null
// the app's own record of each desktop session, which holds the title its sessions list shows
let appSessionsDir: string | null = null
let appRecord: string | null = null
let appTitle = ''
const TITLE_EVERY = 60 // seconds between rereads of the title, which the app may set after the first turn
let mine: { hostId: string; cwd: string; state: SessionStatus; since: number; lastPrompt: string; tool: string } | null = null
let lastBeat = 0
let lastBars = ''
let lastTool = ''
// the desktop (or a phone) attaches to a session while it shows it and detaches when the person leaves it
const viewers = new Set<string>()
const isWaitingOnPerson = (s: SessionStatus) => s === 'done' || s === 'needs_input'
let lastOthers = ''
let pollCount = 0

// writes this session's status; a new state restarts `since`, so a second finish shows again after the first was seen
async function publish($: EngineInterface, state?: SessionStatus) {
  if (!mine || !sessionsDir) return
  const now = await $.clock.now()
  if (state) {
    mine.state = state
    mine.since = now
  }
  lastBeat = now
  const list = await read($, plans)
  const bar = [...list].reverse().find(p => p.id !== AGENTS)
  const bars = barsOf(list)
  lastBars = JSON.stringify(bars)
  lastTool = mine.tool
  const file: SessionFile = { v: 1, hostId: mine.hostId, cwd: mine.cwd, label: bar?.title || mine.lastPrompt, title: appTitle, tool: mine.tool, state: mine.state, since: mine.since, updatedAt: now, bars }
  await $.fs.write(`${sessionsDir}/${mine.hostId}.json`, JSON.stringify(file)).catch(() => undefined)
  // the person is looking at this session as it finishes: the other sessions need not show it
  if (state && isWaitingOnPerson(state) && viewers.size > 0) await writeSeen($, mine.hostId, mine.since)
}

// reads this session's title from the app's record of it (claude-code-sessions/<account>/<org>/<id>.json), the name
// its sessions list shows. That file is the app's own, not an interface: when it is missing or changes shape, the
// title stays empty and the other sessions fall back to the bar's title or the person's last message
async function refreshTitle($: EngineInterface): Promise<boolean> {
  if (!mine || !appSessionsDir) return false
  if (!appRecord) {
    for (const a of await $.fs.list(appSessionsDir).catch(() => [])) {
      if (a.kind !== 'dir') continue
      for (const b of await $.fs.list(`${appSessionsDir}/${a.name}`).catch(() => [])) {
        const path = `${appSessionsDir}/${a.name}/${b.name}/${mine.hostId}.json`
        if (b.kind === 'dir' && (await $.fs.exists(path).catch(() => false))) appRecord = path
      }
    }
    if (!appRecord) return false
  }
  let title = ''
  try {
    const record = JSON.parse((await $.fs.read(appRecord)) as string)
    title = typeof record?.title === 'string' ? str(record.title, 60) : ''
  } catch {
    appRecord = null
  }
  if (title === appTitle) return false
  appTitle = title
  return true
}

// the bars the other sessions draw: shape and state only, no subagent strips, none that is leaving
const barsOf = (list: readonly Plan[]) =>
  list.filter(p => !p.leavingAt).map(p => ({ id: p.id, title: p.title, kind: p.kind, stages: p.stages, state: p.state, note: p.note, startedAt: p.startedAt }))

// a bar read from another session's file, rebuilt through the same checks a model's call goes through
function awayBar(raw: unknown, hostId: string, now: number): Plan | undefined {
  if (!raw || typeof raw !== 'object') return undefined
  const r = raw as Raw
  const p = normalize(r, null, now, `away:${hostId}`)
  if (p.stages.length === 0) return undefined
  return { ...p, startedAt: typeof r.startedAt === 'number' && Number.isFinite(r.startedAt) ? r.startedAt : now }
}

async function readSeen($: EngineInterface): Promise<Record<string, number>> {
  if (!sessionsDir) return {}
  try {
    const v = JSON.parse((await $.fs.read(`${sessionsDir}/${SEEN}`)) as string)
    return v && typeof v === 'object' ? v : {}
  } catch {
    return {}
  }
}

async function pollOthers($: EngineInterface) {
  if (!sessionsDir) return
  const now = await $.clock.now()
  const entries = await $.fs.list(sessionsDir).catch(() => [])
  const seen = await readSeen($)
  const rows: OtherSession[] = []
  for (const entry of entries) {
    if (entry.kind !== 'file' || !entry.name.endsWith('.json') || entry.name === SEEN || now - entry.mtimeMs > KEEP_MS) continue
    let f: SessionFile
    try {
      f = JSON.parse((await $.fs.read(`${sessionsDir}/${entry.name}`)) as string)
    } catch {
      continue
    }
    if (f?.v !== 1 || !HOST_ID.test(f.hostId) || f.hostId === mine?.hostId) continue
    const isShown =
      f.state === 'working' ? now - f.updatedAt < WORKING_FRESH_MS : (f.state === 'done' || f.state === 'needs_input') && now - f.since < KEEP_MS
    // a finish that was seen (opened, switched to, or ✕) hides until the session changes state again;
    // a running session always shows
    if (!isShown || (f.state !== 'working' && f.since <= (seen[f.hostId] ?? 0))) continue
    const bars = (Array.isArray(f.bars) ? f.bars : [])
      .map(raw => ({ isAgents: (raw as Raw | null)?.id === AGENTS, p: awayBar(raw, f.hostId, now) }))
      .filter((b): b is { isAgents: boolean; p: Plan } => b.p !== undefined)
    // its newest task bar, or its subagents' bar when it has no task bar
    const bar = ([...bars].reverse().find(b => !b.isAgents) ?? bars[bars.length - 1])?.p
    rows.push({
      hostId: f.hostId,
      folder: str(projectOf(String(f.cwd)), 40),
      ...(typeof f.title === 'string' && f.title ? { title: str(f.title, 60) } : {}),
      label: readable(f.label, 60),
      state: f.state as OtherSession['state'],
      since: f.since,
      ...(typeof f.tool === 'string' && f.tool ? { tool: str(f.tool, 60) } : {}),
      ...(bar ? { bar } : {}),
      ...(leavingAway.has(f.hostId) ? { isLeaving: true } : {}),
    })
  }
  // waiting on the person first, then finished, then running; the newest first within each
  const rank = { needs_input: 0, done: 1, working: 2 } as const
  rows.sort((a, b) => rank[a.state] - rank[b.state] || b.since - a.since)
  const view = { rows }
  const key = JSON.stringify(view)
  if (key === lastOthers) return
  lastOthers = key
  await update($, others, () => view)
}

// the person has seen this finish: every session stops showing it until that session finishes again
// writes that a session's finish (the state that began at `since`) has been seen, for every session to read
async function writeSeen($: EngineInterface, hostId: string, since: number) {
  if (!sessionsDir) return
  const now = await $.clock.now()
  const seen = await readSeen($)
  seen[hostId] = since
  for (const [id, at] of Object.entries(seen)) if (now - at > KEEP_MS) delete seen[id]
  await $.fs.write(`${sessionsDir}/${SEEN}`, JSON.stringify(seen)).catch(() => undefined)
}

async function markSeen($: EngineInterface, row: OtherSession) {
  await writeSeen($, row.hostId, row.since)
  lastOthers = ''
  await update($, others, v => ({ ...v, rows: v.rows.filter(r => r.hostId !== row.hostId) }))
}

// ✕: the row dims for LEAVE_MS, then leaves; the seen mark is written once it has gone, so a read in between keeps it dimmed
const leavingAway = new Set<string>()
async function dismissAway($: EngineInterface, row: OtherSession) {
  if (leavingAway.has(row.hostId)) return
  leavingAway.add(row.hostId)
  await update($, others, v => ({ ...v, rows: v.rows.map(r => (r.hostId === row.hostId ? { ...r, isLeaving: true } : r)) }))
  $.clock.after(LEAVE_MS, async () => {
    await markSeen($, row)
    leavingAway.delete(row.hostId)
  })
}

async function switchTo($: EngineInterface, row: OtherSession) {
  if (!HOST_ID.test(row.hostId)) return
  await markSeen($, row)
  await $.process.run(['open', linkOf(row.hostId)], { timeoutMs: 5000 }).catch(() => undefined)
}

const STEP_SCHEMA = {
  type: 'object',
  required: ['title', 'status'],
  properties: {
    title: { type: 'string' },
    status: { enum: STATUSES },
    substeps: {
      type: 'array',
      items: { type: 'object', required: ['title', 'status'], properties: { title: { type: 'string' }, status: { enum: STATUSES } } },
    },
  },
}

// only calls that change something count as work for the enforcement below; reading and searching are free
const WORK_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit', 'Bash', 'PowerShell'])
const WORK_BEFORE_PLAN = 3 // the 4th changing call without a plan is refused once
const CALLS_BEFORE_NUDGE = 6 // working calls without a plan update before a reminder


export const register: Register = on => {
  // per-turn bookkeeping; module variables are fine here, a reload just starts a fresh count
  let workCalls = 0
  let sinceUpdate = 0
  let isPlanTouched = false
  let hasRefused = false
  let isWaitingOnBackground = false

  on('turn.start', async ($, e, next) => {
    workCalls = 0
    sinceUpdate = 0
    isPlanTouched = false
    hasRefused = false
    isWaitingOnBackground = false
    isMainTurn = true
    owesDone = false
    await refreshTitle($)
    await publish($, 'working')

    return next(e)
  })

  // the rule lives in the cached system prompt; a message only carries one short line when bars are open,
  // and the person answering clears any "needs input" without a model call
  on('prompt.submit', async ($, e, next) => {
    // the person's own message, typed here or sent from their phone, retires the finished bars;
    // a prompt with no origin is the person's own too
    const origin = e.origin as { kind: string; asUser?: boolean } | undefined
    if (!origin || origin.kind === 'composer' || origin.kind === 'bridge' || (origin.kind === 'plugin' && origin.asUser === true)) {
      await fadeOutDone($)
      // the name other sessions show when this one has no bar: the person's own words, never a turn the system opened
      if (mine) mine.lastPrompt = readable(e.text, 30)
    }
    if (origin?.kind !== 'composer') return next(e)
    const list = await read($, plans)
    if (list.some(p => p.state === 'needs_input')) {
      await update($, plans, all => all.map(p => (p.state === 'needs_input' ? { ...p, state: 'running' as const, note: null } : p)))
    }
    const open = list.filter(p => p.state !== 'done' && p.id !== AGENTS)
    if (open.length === 0) return next(e)
    const line = `plan-progress open bars: ${open
      .map(p => {
        const w = where(p)
        return `${p.id} (${p.stages[w.stage]?.name ?? ''} ${w.step}/${w.stageSize})`
      })
      .join(', ')}`

    return next({ ...e, context: [...(e.context ?? []), line] })
  })

  // watches the main loop's changing calls: refuses once when multi-step work starts without a bar,
  // and reminds to update the bar when it goes stale mid-turn
  on('tool.call', async ($, e, next) => {
    // a subagent's call only names its current tool on its strip; no gate, no reminders
    if (e.agentId) {
      const agentId = e.agentId
      if (!agentHome.has(agentId)) return next(e)
      await editAgent($, agentId, a => ({ ...a, state: 'running', tool: e.tool }))
      if (e.tool_use_id) toolUses.set(e.tool_use_id, agentId)
      const ran = await next(e)
      if (e.tool_use_id) toolUses.delete(e.tool_use_id)
      if (waiting.delete(agentId)) await editAgent($, agentId, a => (a.state === 'waiting' ? { ...a, state: 'running' } : a))
      return ran
    }
    // the tool the main loop runs now, which other sessions show beside a session that has no bar
    if (mine && e.tool !== TOOL) mine.tool = e.tool
    if (!WORK_TOOLS.has(e.tool)) return next(e)
    isWaitingOnBackground = (e as unknown as Raw).run_in_background === true
    const hasLivePlan = isPlanTouched || (await read($, plans)).some(isOpenPlan)
    if (!hasLivePlan && !hasRefused && workCalls >= WORK_BEFORE_PLAN) {
      hasRefused = true

      return { deny: `plan-progress: several changes ahead. Create a bar with ${TOOL} first, then retry.` }
    }
    const ran = await next(e)
    // a shell call that only read (ls, git status, grep) is not work
    if (ran.deny !== undefined || ran.isReadOnly) return ran
    workCalls += 1
    sinceUpdate += 1
    if (hasLivePlan && sinceUpdate >= CALLS_BEFORE_NUDGE) {
      sinceUpdate = 0

      return { ...ran, context: [...(ran.context ?? []), `plan-progress: bar is stale, send {id, next:true} or {id, done, active}.`] }
    }

    return ran
  })

  // an open bar at the end of a turn: a question to the user marks it waiting on its own;
  // only a turn that did work and left the bar unexplained is sent back once
  on('classic.Stop', async ($, e, next) => {
    const result = await next(e)
    if (e.stop_hook_active || result.block || isWaitingOnBackground || (e.background_tasks?.length ?? 0) > 0) return result
    const open = (await read($, plans)).filter(isOpenPlan)
    if (open.length === 0) return result
    const asks = /[?？]\s*$/.test(e.last_assistant_message ?? '')
    if (asks) {
      const last = open[open.length - 1]
      if (last) await putPlan($, { ...last, state: 'needs_input' })

      return result
    }
    if (workCalls === 0 && !isPlanTouched) return result

    return {
      ...result,
      block: `plan-progress: ${open.map(p => p.id).join(', ')} still open. Update each with ${TOOL}: {id, next:true}, or state "done", "needs_input" or "error" with a note.`,
    }
  })

  on('session.start', async ($, e, next) => {
    await $.tool.register({
      name: 'plan_progress',
      description: 'Live progress bar above the prompt, one per id. Create with title + stages; update with short ops (next, done, active, failed) or state.',
      inputSchema: {
        type: 'object',
        required: ['id'],
        properties: {
          id: { type: 'string', description: 'Bar id; reuse it for updates' },
          title: { type: 'string' },
          kind: { enum: ['plan', 'todo'] },
          stages: {
            type: 'array',
            description: 'Full breakdown, only when creating or restructuring',
            items: { type: 'object', required: ['name', 'steps'], properties: { name: { type: 'string' }, steps: { type: 'array', items: STEP_SCHEMA } } },
          },
          next: { type: 'boolean', description: 'Active step finished, start the next one' },
          done: { type: 'array', items: { type: 'string' }, description: 'Step titles now finished' },
          active: { type: 'string', description: 'Step title now in progress' },
          failed: { type: 'string', description: 'Step title that failed' },
          state: { enum: ['running', 'needs_input', 'error', 'done'] },
          note: { type: 'string', description: 'One line for needs_input or error' },
        },
      },
    })
    const saved = await $.store.get(STYLE_STORE_KEY)
    if (isStyleId(saved)) await update($, barStyle, () => saved)
    const savedView = await $.store.get(AGENT_VIEW_STORE_KEY)
    if (isAgentView(savedView)) await update($, agentView, () => savedView)
    const savedAccent = await $.store.get(ACCENT_STORE_KEY)
    if (isAccentId(savedAccent)) {
      setAccent(savedAccent)
      await update($, accentChoice, () => savedAccent)
    }
    const savedShown = await $.store.get(SHOWN_STORE_KEY)
    if (typeof savedShown === 'boolean') await update($, isOpen, () => savedShown)
    const savedSounds = await $.store.get(SOUNDS_STORE_KEY)
    if (typeof savedSounds === 'boolean') await update($, soundsOn, () => savedSounds)
    isDarkTheme = String((await $.config.list()).find(row => row.key === 'theme')?.value ?? '').includes('dark')
    const savedCollapsed = await $.store.get(COLLAPSED_STORE_KEY)
    if (typeof savedCollapsed === 'boolean') await update($, isCollapsed, () => savedCollapsed)
    const savedCross = await $.store.get(CROSS_STORE_KEY)
    if (typeof savedCross === 'boolean') await update($, crossOn, () => savedCross)
    // a desktop session names itself in its environment; a terminal session has no id to switch to and only reads
    const home = await $.env.get('HOME')
    const hostId = await $.env.get('CLAUDE_CODE_HOST_SESSION_ID')
    if (home) sessionsDir = `${home}/.claude/plan-progress/sessions`
    if (home) appSessionsDir = `${home}/Library/Application Support/Claude/claude-code-sessions`
    if (hostId && HOST_ID.test(hostId)) mine = { hostId, cwd: await $.session.cwd(), state: 'idle', since: await $.clock.now(), lastPrompt: '', tool: '' }
    await refreshTitle($)
    $.clock.every(1000, async () => {
      // a bar that moved reaches the other sessions within a second; a working session also beats every 30 s
      const isBarMoved = mine !== null && (JSON.stringify(barsOf(await read($, plans))) !== lastBars || mine.tool !== lastTool)
      if (isBarMoved || (mine?.state === 'working' && (await $.clock.now()) - lastBeat >= HEARTBEAT_MS)) await publish($)
      pollCount += 1
      if (pollCount % POLL_EVERY === 0 && (await read($, crossOn))) await pollOthers($)
      if (pollCount % TITLE_EVERY === 0 && (await refreshTitle($))) await publish($)
      // the hairline style shows elapsed time, so it redraws every second while a bar runs
      const isTiming = (await styleOf($)) === 'hairline' && (await read($, plans)).some(p => p.state !== 'done')
      const isAwayTiming = (await read($, crossOn)) && (await read($, others)).rows.some(r => r.state === 'working' && !r.bar)
      if (isTiming || isAwayTiming || agentHome.size > 0 || (await $.clock.now()) < foldUntil) await update($, tick, n => n + 1)
    })
    await $.command.register({ name: 'progress', description: 'Show or hide the progress bars' })
    await $.command.register({ name: 'progress-style', description: 'Switch the progress bar style (no argument lists them, "next" cycles)' })
    await $.command.register({ name: 'progress-demo', description: 'Show a sample plan in the progress bars' })
    await $.command.register({ name: 'progress-sounds', description: 'Play the decision, error and done sounds' })
    await $.command.register({ name: 'progress-clear', description: 'Remove all progress bars' })

    return next(e)
  })

  on('prompt.compose', async ($, e, next) => {
    const result = await next(e)

    return { sections: [...result.sections, { id: 'plan-progress:rules', text: RULES, scope: 'session' as const }] }
  })

  on('tool.call', { tool: TOOL }, async ($, e) => {
    const raw = e as unknown as Raw
    const now = await $.clock.now()
    const list = await read($, plans)
    const id = slug(str(raw.id, 60) || str(raw.title, 80))
    const next = normalize(raw, list.find(p => p.id === id) ?? null, now, id)
    if (next.stages.length === 0) return { deny: `plan_progress: no bar "${id}" yet; create it with title and stages.` }
    isPlanTouched = true
    sinceUpdate = 0
    // finished mid-turn: the bar holds at its last step until the turn ends, so done comes after the reply
    const prevState = list.find(p => p.id === id)?.state
    const isHeld = isMainTurn && next.state === 'done' && prevState !== 'done'
    await putPlan($, isHeld ? { ...next, state: 'running', isFinishing: true } : next)
    const w = where(next)

    const active = next.stages.flatMap(st => st.steps).find(st => st.status === 'active')

    return { result: `${id}: ${Math.min(w.pos, w.total)}/${w.total}, ${next.state}${active ? `, active "${active.title}"` : ''}` }
  })

  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    const live = (await read($, plans)).filter(p => p.state === 'running' && !p.isFinishing).pop()
    if (live) await update($, plans, list => list.map(p => (p.id === live.id ? { ...p, state: 'needs_input' as const } : p)))
    play($, 'decision')
    await publish($, 'needs_input')
    const ran = await next(e)
    if (live) await update($, plans, list => list.map(p => (p.id === live.id && p.state === 'needs_input' ? { ...p, state: 'running' as const } : p)))
    await publish($, 'working')

    return ran
  })

  on('tool.call', { tool: 'ExitPlanMode' }, async ($, e, next) => {
    play($, 'decision')
    const ran = await next(e)
    const text = ran.deny === undefined && ran.isError !== true ? (ran.result as { plan?: unknown } | undefined)?.plan : undefined
    if (typeof text === 'string') {
      const parsed = parsePlan(text, await $.clock.now())
      if (parsed) await putPlan($, { ...parsed, id: slug(parsed.title) })
    }

    return ran
  })

  on('command.run', { command: 'progress' }, async $ => {
    const open = await read($, isOpen)
    await setShown($, !open)
    const hasBars = (await read($, plans)).length > 0

    return { text: `${open ? 'Progress bars hidden.' : 'Progress bars shown.'}${hasBars ? '' : ' No plan yet. /progress-demo shows a sample.'}` }
  })

  on('command.run', { command: 'progress-demo' }, async $ => {
    await putPlan($, DEMO(await $.clock.now()))
    // asked for by the person, so it shows the bars again
    await setShown($, true)

    return { text: 'Sample plan shown above the prompt.' }
  })

  on('command.run', { command: 'progress-style' }, async ($, e) => {
    const current = await styleOf($)
    const arg = e.args.trim().toLowerCase()
    const list = STYLE_IDS.map(id => `${id === current ? '▸' : ' '} ${id.padEnd(9)} ${STYLE_INFO[id]}`).join('\n')
    if (!arg) {
      await $.ui.open({ id: STYLE_PANE, title: STYLE_PANE_TITLE })
      return { text: `目前風格：${current}（已打開樣式面板）\n${list}\n\n用法：/progress-style <名稱>，或 /progress-style next 換下一個` }
    }
    const nextId = arg === 'next' ? STYLE_IDS[(STYLE_IDS.indexOf(current) + 1) % STYLE_IDS.length] : arg
    if (!isStyleId(nextId)) return { text: `沒有「${arg}」這個風格。\n${list}` }
    await setStyle($, nextId)
    const hasBars = (await read($, plans)).length > 0
    return { text: `已切換到 ${nextId}：${STYLE_INFO[nextId]}${hasBars ? '' : '\n現在沒有進度條，用 /progress-demo 看樣子。'}` }
  })

  on('command.run', { command: 'progress-clear' }, async $ => {
    await update($, plans, () => [])

    return { text: 'Progress bars removed.' }
  })

  on('command.run', { command: 'progress-sounds' }, async $ => {
    // asked for by the person, so it plays even with sounds off
    playNow($, 'decision')
    $.clock.after(900, () => playNow($, 'error'))
    $.clock.after(1800, () => playNow($, 'done'))

    return { text: 'Sounds: decision, error, done.' }
  })

  // always drawn, so the person sees the mod is loaded: one gear that opens the style pane.
  // A Button: the desktop draws it with a native grey box, but its footer draws no Client
  // region and no pressable Markdown link (0.5.7-0.5.10), so a Button is the one control that works there;
  // one glyph keeps that box small and has no descender to clip
  // the gear lives in the band above the prompt, not the footer: the desktop app (2.37337) gives a plugin's footer
  // labels a row of their own, a whole row for one glyph. Without bars the band is empty and /progress-style opens the pane

  // four settings, each a press away: whether the bars show, whether sounds play, how subagents show,
  // then one bordered tile per style with its preview
  on('ui.render', { component: 'Pane', requestId: STYLE_PANE }, async ($, e) => {
    const t = $.ui.resolve(e)
    const { Box, Button, Text } = t
    const Svg = 'Svg' in t ? t.Svg : null
    const current = await styleOf($)
    const view = await agentViewOf($)
    const pickedAccent = await read($, accentChoice)
    const isShown = await read($, isOpen)
    const isSounding = await read($, soundsOn)
    const isCross = await read($, crossOn)
    const now = await $.clock.now()
    const W = Math.max(200, Math.min(460, (e.props.bodyColumns || 50) * 8 - 24))
    // a tile's border and padding take about three columns
    const tileW = W - 24
    const sampleAgents: AgentRun[] = [
      { id: 'pa1', title: '讀取模組', state: 'running', tool: 'Read', startedAt: now - 48_000, endedAt: null, depth: 0 },
      { id: 'pa2', title: '量 API 延遲', state: 'done', tool: 'Done', startedAt: now - 72_000, endedAt: now - 6_000, depth: 0 },
      { id: 'pa3', title: '比對打包大小', state: 'waiting', tool: 'Needs approval', startedAt: now - 9_000, endedAt: null, depth: 0 },
    ]
    const agentsSample = { ...DEMO(now), id: 'preview-agents', agents: sampleAgents }
    const allAgents = { shown: sampleAgents, hidden: [] }
    // the slot keeps the expanded height in every mode, so switching modes never moves the list below
    const agentsSlotH = drawBar(current, agentsSample, W, now, allAgents).height
    const agentsDrawn = inSlot(drawBar(current, agentsSample, W, now, applyAgentView(allAgents, view)), W, agentsSlotH, 'top')
    // every style's preview sits centred in one slot as tall as the tallest, so all tiles share one size
    const previews = new Map(STYLE_IDS.map(id => [id, drawBar(id, { ...DEMO(now), id: `preview-${id}` }, tileW, now, null)] as const))
    const previewSlotH = Math.max(...[...previews.values()].map(d => d.height))

    return (
      <Box flexDirection="column" gap={2}>
        {/* the two on/off settings side by side; save and close stays at the top right */}
        <Box key="settings-row" flexDirection="row" alignItems="flex-end" gap={3}>
          <Box flexDirection="column" gap={1}>
            <Text bold>進度條</Text>
            <Box key="bars-row" flexDirection="row" alignItems="center" gap={1}>
              {([true, false] as const).map(shown => (
                <Button
                  key={shown ? 'bars-shown' : 'bars-hidden'}
                  variant={shown === isShown ? 'primary' : 'secondary'}
                  label={shown ? '顯示' : '隱藏'}
                  onPress={() => (shown === isShown ? undefined : setShown($, shown))}
                />
              ))}
            </Box>
          </Box>
          <Box flexDirection="column" gap={1}>
            <Text bold>提示音</Text>
            <Box key="sounds-row" flexDirection="row" alignItems="center" gap={1}>
              {([true, false] as const).map(isOn => (
                <Button
                  key={isOn ? 'sounds-on' : 'sounds-off'}
                  variant={isOn === isSounding ? 'primary' : 'secondary'}
                  label={isOn ? '開' : '關'}
                  onPress={() => (isOn === isSounding ? undefined : setSounds($, isOn))}
                />
              ))}
            </Box>
          </Box>
          <Box flexGrow={1} />
          {/* every press in the pane already saved; this one only closes it */}
          <Button key="save-close" variant="primary" label="儲存並關閉" onPress={() => $.ui.close({ id: STYLE_PANE })} />
        </Box>

        <Box flexDirection="column" gap={1}>
          <Text bold>其他 session</Text>
          <Box key="cross-row" flexDirection="row" alignItems="center" gap={1}>
            {([true, false] as const).map(isOn => (
              <Button
                key={isOn ? 'cross-on' : 'cross-off'}
                variant={isOn === isCross ? 'primary' : 'secondary'}
                label={isOn ? '開' : '關'}
                onPress={() => (isOn === isCross ? undefined : setCross($, isOn))}
              />
            ))}
          </Box>
        </Box>

        <Box flexDirection="column" gap={1}>
          <Text bold>Subagent 顯示</Text>
          <Box key="agents-row" flexDirection="row" alignItems="center" gap={1}>
            {AGENT_VIEWS.map(k => (
              <Button
                key={`agents-${k}`}
                variant={k === view ? 'primary' : 'secondary'}
                label={AGENT_VIEW_LABEL[k]}
                onPress={() => (k === view ? undefined : setAgentView($, k))}
              />
            ))}
          </Box>
          {Svg ? [<Svg key="agents-preview" source={agentsDrawn.svg} alt={`subagents ${view} preview`} width={W} height={agentsDrawn.height} />] : []}
        </Box>

        {/* the running colour for every style, one named button each. No colour dots: a desktop's native button ignores
            a colour inside it and a drawing takes no press, so a dot could not be the thing pressed, and a dot that cannot
            be pressed beside a word reads wrong (0.5.48-0.5.51 tried); the tiles below redraw in the colour */}
        <Box flexDirection="column" gap={1}>
          <Text bold>顏色</Text>
          <Box key="accent-row" flexDirection="row" alignItems="center" gap={1} flexWrap="wrap">
            {['', ...ACCENT_IDS].map(id => {
              const isPicked = id === pickedAccent
              return (
                <Button
                  key={`use-accent-${id || 'own'}`}
                  variant={isPicked ? 'primary' : 'secondary'}
                  label={isAccentId(id) ? ACCENT_INFO[id].name : '跟樣式預設'}
                  onPress={() => (isPicked ? undefined : setAccentChoice($, id))}
                />
              )
            })}
          </Box>
        </Box>

        {/* tiles name no width (a Box width counts cells, not pixels); the column stretches them all to the pane's width */}
        <Box key="style-list" flexDirection="column" alignItems="stretch" gap={1}>
          <Text bold>進度條樣式</Text>
          {STYLE_IDS.map(id => {
            const isCurrent = id === current
            const drawn = inSlot(previews.get(id) ?? { svg: '', height: 0 }, tileW, previewSlotH, 'center')
            const name = STYLE_INFO[id].split('：')[0]
            // black and white like the pane's buttons: the current tile's border at full strength, the rest dim
            const frame = isCurrent ? {} : { borderDimColor: true }

            return (
              <Box key={`style-${id}`} flexDirection="column" gap={1} borderStyle="round" paddingX={1} {...frame}>
                <Box flexDirection="row" alignItems="center" gap={1}>
                  <Text bold>{name}</Text>
                  <Text dimColor>{id}</Text>
                  <Box flexGrow={1} />
                  <Button
                    key={`use-${id}`}
                    variant={isCurrent ? 'primary' : 'secondary'}
                    label={isCurrent ? '✓ 使用中' : '使用'}
                    onPress={() => (isCurrent ? undefined : setStyle($, id))}
                  />
                </Box>
                {Svg ? [<Svg key={`preview-${id}`} source={drawn.svg} alt={`${id} preview`} width={tileW} height={drawn.height} />] : []}
              </Box>
            )
          })}
        </Box>
      </Box>
    )
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    await read($, accentChoice)
    const list = await read($, plans)
    // other sessions that finished or wait on the person, under this session's own bars
    const away: OthersView = (await read($, crossOn)) ? await read($, others) : { rows: [] }
    const hasAway = away.rows.length > 0
    const shownAway = away.rows.slice(0, MAX_OTHERS)
    // the name the app's sessions list shows; without it (an older plugin, or the app's record unread), folder and bar title
    const awayTitle = (r: OtherSession) => {
      if (r.title) return r.title
      const name = r.bar?.title || r.label
      return name ? `${r.folder} · ${name}` : r.folder
    }
    if ((list.length === 0 && !hasAway) || e.props.hasSurvey || !(await read($, isOpen))) return next(e)
    // folded, the band holds no rows: only a button at its middle that opens it, saying how many rows it hides
    // (0.5.56-0.5.61 kept one row; with the button on the band's top edge that row ran under it)
    const rowCount = list.length + away.rows.length
    const canFold = rowCount > 1
    const isFolded = canFold && (await read($, isCollapsed))
    const ownShown = list
    const awayShown = shownAway
    const t = $.ui.resolve(e)
    const { Box, Button, Text } = t
    const Svg = 'Svg' in t ? t.Svg : null
    // on the desktop rows are spaced in px (ROW_GAP_PX, FRAME_GAP_PX), not in whole rows as in a terminal
    const isTight = Boolean(Svg) && e.surface !== 'terminal'
    if (isFolded) {
      return (
        <Box key="band-fold" flexDirection="row" justifyContent="center" flexGrow={1}>
          <Button key="band-fold-button" plain dimColor label={`${FOLD_DOWN} ${rowCount}`} onPress={() => setCollapsed($, false)} />
        </Box>
      )
    }
    const foldBeside = canFold && e.surface === 'terminal'
    const total = Math.max(320, ((e.props.bodyColumns || 100) - GEAR_CELLS - (foldBeside ? FOLD_CELLS : 0)) * 8)
    // every bar has the same width and is pinned to the right edge (fixed-width percent, close button),
    // so rows line up whatever their titles; the slack goes into the gap after the title.
    // Desktop reports ~8 CSS px per column; glyph, gaps, percent and the close button take ~126 px.
    const titleWidth = Math.min(
      Math.round(total * 0.4),
      // rounded up: rounded to the nearest, a title of 91.2 px got a 91 px column and fitTitle cut its last letter (0.5.68)
      Math.max(0, ...list.map(p => Math.ceil(textWidth(p.title, 6.4))), ...shownAway.map(r => Math.ceil(textWidth(awayTitle(r), 6.4)))),
    )
    // a button label cannot truncate itself, so every title is cut to the title column here
    const fitTitle = (s: string) => {
      let shown = s
      while (shown.length > 3 && textWidth(shown, 6.4) > titleWidth) shown = shown.slice(0, -1)
      return shown === s ? s : shown.trimEnd() + '…'
    }
    const style = await styleOf($)
    const look = style === 'original' ? null : STYLES[style]
    const view = await agentViewOf($)
    // the hairline's elapsed time is wider than a percent
    // with other sessions under it, this session's own bars sit in a rounded frame; every row gives up the frame's width
    // (its border and padding) so the bars inside and outside it still line up
    const isFramed = ownShown.length > 0 && awayShown.length > 0
    // the desktop draws the glyph in a box of one width; a terminal's cells already line it up
    const glyphCell = (gl: { char: string; color: string }, isDim?: boolean) =>
      Svg && e.surface !== 'terminal' ? (
        <Svg key="glyph" source={glyphSvg(gl.char, gl.color, isDim)} alt={`狀態：${GLYPH_WORD[gl.char] ?? gl.char}`} width={GLYPH_W} height={GLYPH_H} />
      ) : (
        <Text key="glyph" color={gl.color} dimColor={isDim}>
          {gl.char}
        </Text>
      )
    const frameName = frameNameSvg(str(appTitle || '這個 session', 40))
    const frameSlack = isFramed ? FRAME_PX : 0
    const trackW = Math.max(120, Math.min(1400, total - titleWidth - 140 - frameSlack - (style === 'hairline' ? 18 : 0)))
    await read($, tick)
    const now = await $.clock.now()
    // the text right of each bar sits in a column as wide as the widest of them, so every bar's left edge lines up
    const rightOf = (p: Plan) => {
      const w = where(p)
      const pct = p.state === 'done' ? 100 : Math.round((Math.min(w.pos, w.total) / Math.max(1, w.total)) * 100)
      return look && Svg ? look.right(p, now) : `${String(pct).padStart(3, FIGURE_SPACE)}%`
    }
    // one cell more than the longest text: a cell is about 8 px, a wide letter (m, %) a little more than one
    // a running session with no bar shows how long it has run there instead
    const awayRight = (r: OtherSession) => (r.bar ? rightOf(r.bar) : r.state === 'working' ? elapsed(now - r.since) : '')
    const rightCells = 1 + Math.max(4, ...list.map(p => rightOf(p).length), ...shownAway.map(r => awayRight(r).length))
    // a hairline between task bars, so each bar and its agent strips read as one group
    const lineW = total - frameSlack
    const divider = `<svg xmlns="http://www.w3.org/2000/svg" width="${lineW}" height="1"><rect width="${lineW}" height="1" fill="#808080" fill-opacity=".22"/></svg>`

    const ownRows = ownShown.flatMap((p, i) => {
          const v = applyAgentView(visibleAgents(p, now), view)
          const drawn = drawBar(style, p, trackW, now, v)
          const isLeaving = Boolean(p.leavingAt)
          const source = isLeaving ? fadeOut(drawn.svg, trackW, drawn.height) : drawn.svg
          const glyph = look ? look.glyph(p) : { char: STATE_GLYPH[p.state], color: STATE_COLOR[p.state] }
          const agentsAlt = v ? `; agents: ${(p.agents ?? []).map(a => `${a.title} ${a.state}`).join(', ')}` : ''
          // the desktop draws no Svg with an empty alt, so there the line only took room: a second gap between two bars
          const line = i > 0 && Svg && !isTight ? [<Svg key={`div-${p.id}`} source={divider} alt="" width={lineW} height={1} />] : []
          const w = where(p)
          const pct = p.state === 'done' ? 100 : Math.round((Math.min(w.pos, w.total) / Math.max(1, w.total)) * 100)
          const color = STATE_COLOR[p.state]
          const stageName = p.stages[w.stage]?.name ?? ''
          const alt =
            p.state === 'done'
              ? `${p.title}: done, ${plural(w.total, 'step')}`
              : `${p.title}: ${stageName}, step ${w.step} of ${w.stageSize}, ${pct}%${p.note ? ` — ${p.note}` : ''}${agentsAlt}`
          const bar = `${'━'.repeat(Math.round(pct / 4))}${'─'.repeat(25 - Math.round(pct / 4))}`

          return [
            ...line,
            <Box key={`bar-${p.id}`} flexDirection="row" alignItems={v || drawn.height > TRACK_H ? 'flex-start' : 'center'} gap={1}>
              {glyph ? [glyphCell(glyph, isLeaving)] : []}
              {/* a plain button like the other sessions' titles, so both start at the same place; it does nothing when pressed */}
              <Button key={`title-${p.id}`} plain dimColor={isLeaving} label={fitTitle(p.title)} onPress={() => undefined} />
              <Box flexGrow={1} />
              {Svg ? (
                <Svg source={source} alt={alt} width={trackW} height={drawn.height} />
              ) : (
                <Text>
                  <Text color={color}>{bar.replace(/─/g, '')}</Text>
                  <Text dimColor>{bar.replace(/━/g, '')}</Text>
                  <Text color={color}>{` ${stageName} ${w.step}/${w.stageSize}`}</Text>
                </Text>
              )}
              <Box width={rightCells} justifyContent="flex-end">
                <Text dimColor>{rightOf(p)}</Text>
              </Box>
              <Box width={CLOSE_CELLS} justifyContent="center">
                <Button key={`close-${p.id}`} plain dimColor label="✕" onPress={() => dropPlan($, p.id)} />
              </Box>
            </Box>,
          ]
        })
    const awayRows = [
          // each other session as one bar row: its title is the button that switches to it
          ...awayShown.map(r => {
            const asState: PlanState = r.state === 'working' ? 'running' : r.state
            // a session waiting on the person shows its bar amber even when the bar itself still says running
            const p = r.bar ? { ...r.bar, state: r.state === 'needs_input' && r.bar.state === 'running' ? ('needs_input' as const) : r.bar.state } : null
            const drawn = p ? drawBar(style, p, trackW, now, null) : null
            const source = drawn ? (r.isLeaving ? fadeOut(drawn.svg, trackW, drawn.height) : drawn.svg) : ''
            // with no bar, the style still picks the glyph and its colour, from the session's state alone
            const stub: Plan = { id: '', title: '', kind: 'plan', stages: [], state: asState, note: null, startedAt: 0 }
            const glyph = look ? look.glyph(p ?? stub) : { char: STATE_GLYPH[p?.state ?? asState], color: STATE_COLOR[p?.state ?? asState] }
            const runColor = accentGlyph() ?? (look?.glyph(stub) ?? null)?.color ?? STATE_COLOR.running
            const status = r.state === 'done' ? '跑完了' : r.state === 'needs_input' ? '等你決定' : '在跑'
            const w = p ? where(p) : null
            const pct = p && w ? (p.state === 'done' ? 100 : Math.round((Math.min(w.pos, w.total) / Math.max(1, w.total)) * 100)) : 0
            const textBar = `${'━'.repeat(Math.round(pct / 4))}${'─'.repeat(25 - Math.round(pct / 4))}`

            return (
              <Box key={`away-${r.hostId}`} flexDirection="row" alignItems={drawn && drawn.height > TRACK_H ? 'flex-start' : 'center'} gap={1}>
                {glyph ? [glyphCell(glyph, r.isLeaving)] : []}
                <Button key={`switch-${r.hostId}`} plain dimColor={r.isLeaving} label={fitTitle(awayTitle(r))} onPress={() => switchTo($, r)} />
                <Box flexGrow={1} />
                {p && drawn && Svg ? (
                  <Svg source={source} alt={`${awayTitle(r)}: ${status}`} width={trackW} height={drawn.height} />
                ) : p ? (
                  <Text>
                    <Text color={STATE_COLOR[p.state]}>{textBar.replace(/─/g, '')}</Text>
                    <Text dimColor>{textBar.replace(/━/g, '')}</Text>
                  </Text>
                ) : Svg && r.state === 'working' ? (
                  <Svg source={runningSvg(toolLabel(r.tool), trackW, runColor)} alt={`${awayTitle(r)}: ${toolLabel(r.tool)}`} width={trackW} height={TRACK_H} />
                ) : Svg ? (
                  // no bar to draw: the word sits where the bars start, in a drawing as wide as theirs
                  <Svg source={statusSvg(status, trackW)} alt={`${awayTitle(r)}: ${status}`} width={trackW} height={TRACK_H} />
                ) : (
                  <Text dimColor>{r.state === 'working' ? toolLabel(r.tool) : status}</Text>
                )}
                <Box width={rightCells} justifyContent="flex-end">
                  <Text dimColor>{awayRight(r)}</Text>
                </Box>
                {/* a running session always shows, so it has no ✕; the empty cell keeps its bar in line */}
                <Box width={CLOSE_CELLS} justifyContent="center">
                  {r.state === 'working' ? [] : [<Button key={`seen-${r.hostId}`} plain dimColor label="✕" onPress={() => dismissAway($, r)} />]}
                </Box>
              </Box>
            )
          }),
          ...(away.rows.length > MAX_OTHERS ? [<Text key="away-more" dimColor>{`還有 ${away.rows.length - MAX_OTHERS} 個 session`}</Text>] : []),
        ]

    // on the desktop a whole row's gap under the frame left the first other session further from the framed bar than the
    // rows below it are from each other (41 px against 31, measured); no gap and a few px of nothing there instead
    const frameGapPx = isFramed && Svg && e.surface !== 'terminal' ? FRAME_GAP_PX : null
    const frameGapSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="1" height="${FRAME_GAP_PX}"/>`
    // the desktop puts ROW_GAP_PX of nothing between rows instead of a row's gap; a terminal keeps its whole-row gap
    const rowGap = isTight ? 0 : 1
    const rowGapSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="1" height="${ROW_GAP_PX}"/>`
    const spaced = (group: string, items: JSX.Element[]) =>
      isTight && Svg ? items.flatMap((item, i) => (i === 0 ? [item] : [<Svg key={`${group}-gap-${i}`} source={rowGapSvg} alt="間距：列" width={1} height={ROW_GAP_PX} />, item])) : items
    const foldLabel = FOLD_UP
    const foldButton = <Button key="band-fold-button" plain dimColor label={foldLabel} onPress={() => setCollapsed($, true)} />
    // the cells the button and the grey behind it take: its label and a cell either side
    const foldCells = foldLabel.length + 2
    // the rows, and the gear at the top right in a column of its own beside them, so it takes no row
    return (
      <Box flexDirection="row" alignItems="flex-start">
      <Box flexDirection="column" gap={isFramed ? (frameGapPx === null ? 1 : 0) : rowGap} flexGrow={1}>
        {isFramed
          ? [
              <Box key="own-frame" flexDirection="column" gap={rowGap} borderStyle="round" borderDimColor paddingX={1}>
                {/* this session's name, the one the other sessions show for it, sits on the frame's top line: on the
                    desktop its drawing's background hides the line behind it, a terminal writes the letters over the line's cells */}
                <Box key="frame-name" position="absolute" top={-1} left={1}>
                  {Svg && e.surface !== 'terminal' ? (
                    <Svg source={frameName.svg} alt={frameName.text} width={frameName.width} height={FRAME_NAME_H} />
                  ) : (
                    <Text dimColor>{` ${frameName.text} `}</Text>
                  )}
                </Box>
                {spaced('own', ownRows)}
              </Box>,
              ...(frameGapPx === null ? [] : [<Svg key="frame-gap" source={frameGapSvg} alt="間距：外框" width={1} height={frameGapPx} />]),
              // the other sessions keep the frame's inset, without its line, so their bars stay under the framed ones
              // (on the desktop they sit 1 px left of the framed rows, the frame's line; a border coloured "transparent"
              // to match it is drawn black there, 0.5.54)
              <Box key="away-list" flexDirection="column" gap={rowGap} paddingX={e.surface === 'terminal' ? FRAME_INSET + 1 : FRAME_INSET}>
                {spaced('away', awayRows)}
              </Box>,
            ]
          : spaced('rows', [...ownRows, ...awayRows])}
      </Box>
      {canFold ? (
        foldBeside ? (
          <Box key="band-fold" width={FOLD_CELLS} justifyContent="flex-end">
            {foldButton}
          </Box>
        ) : (
          // one row up the button showed only its bottom, cut by the band's edge (0.5.57); two rows tall from there with
          // the button at its middle, as the frame's name is drawn, its middle sits on the tree's top edge
          <Box key="band-fold" position="absolute" top={-1} height={2} width={foldCells} flexDirection="column" justifyContent="center" alignItems="center" left={Math.max(0, Math.floor((e.props.bodyColumns || 100) / 2) - Math.floor(foldCells / 2))}>
            {/* the grey only where a frame's line runs under it: with no frame the first row starts right there, and the
                grey covered the top of its text (0.5.63) */}
            <Box key="band-fold-front" width={foldCells} justifyContent="center" {...(isFramed ? { backgroundColor: isDarkTheme ? BAND_GREY.dark : BAND_GREY.light } : {})}>
              {foldButton}
            </Box>
          </Box>
        )
      ) : (
        []
      )}
      <Box key="band-gear" width={GEAR_CELLS} justifyContent="flex-end">
        <Button key="progress-style" plain dimColor label={SETTINGS_GLYPH} onPress={() => openStyles($)} />
      </Box>
      </Box>
    )
  })

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    if (!('agentId' in started) || !started.agentId) return started
    const id = started.agentId
    const now = await $.clock.now()
    const parentHome = e.parentAgentId ? agentHome.get(e.parentAgentId) : undefined
    const home = parentHome ?? [...(await read($, plans))].reverse().find(isOpenPlan)?.id ?? AGENTS
    agentHome.set(id, home)
    const run: AgentRun = {
      id,
      title: (e.description || e.subagentType).slice(0, 60),
      state: 'running',
      tool: 'Starting',
      startedAt: now,
      endedAt: null,
      depth: parentHome ? 1 : 0,
    }
    await update($, plans, list => {
      if (list.some(p => p.id === home)) return list.map(p => (p.id === home ? addRun(p, run, e.parentAgentId, now) : p))
      const auto: Plan = { id: AGENTS, title: 'Agents', kind: 'todo', stages: [], state: 'running', note: null, startedAt: now }
      return placeBar(list, addRun(auto, run, undefined, now))
    })

    return started
  })

  // an agent waiting on a permission prompt turns its strip amber until the call goes on
  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    const agentId = e.tool_use_id ? toolUses.get(e.tool_use_id) : undefined
    const useId = e.tool_use_id
    // the mode often settles an ask by itself in a blink; only a call still held after a moment waits on the person
    if (agentId && useId && verdict.decision === 'ask') {
      $.clock.after(600, async () => {
        if (toolUses.get(useId) !== agentId) return
        waiting.add(agentId)
        await editAgent($, agentId, a => ({ ...a, state: 'waiting', tool: 'Needs approval' }))
      })
    }

    return verdict
  })

  // the desktop attaches while it shows this session: opened from the list, a notification or a bar's title,
  // a finish waiting here is seen, so the other sessions stop showing it
  on('session.attach', async ($, e, next) => {
    viewers.add(e.clientId)
    if (mine && isWaitingOnPerson(mine.state)) await writeSeen($, mine.hostId, mine.since)
    // the person has opened this session and seen its finished bars: they fade out, as after their next message
    await fadeOutDone($)

    return next(e)
  })

  on('session.detach', async ($, e, next) => {
    viewers.delete(e.clientId)

    return next(e)
  })

  // a closed session leaves the other sessions' lists
  on('session.end', async ($, e, next) => {
    await publish($, 'ended')

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const agentId = e.agentId
    if (agentId && agentHome.has(agentId)) {
      const now = await $.clock.now()
      const isFailed = e.reason !== 'answer'
      const tool = e.reason === 'aborted' ? 'Stopped' : isFailed ? 'Failed' : 'Done'
      await editAgent($, agentId, a => ({ ...a, state: isFailed ? 'error' : 'done', tool, endedAt: now }))
      // the mod's own bar sounds through its state; a strip on a task bar sounds here
      if (isFailed && agentHome.get(agentId) !== AGENTS) play($, 'error')
      agentHome.delete(agentId)
      waiting.delete(agentId)
    }
    // when the main turn ends, a plan whose steps are all finished, or one the model finished mid-turn, closes itself;
    // the done sound owed by this turn plays once, after the reply
    if (!agentId) {
      for (const p of await read($, plans)) {
        if (p.id === AGENTS) continue
        if (p.state === 'done') continue
        const steps = p.stages.flatMap(s => s.steps)
        if (p.isFinishing || (steps.length > 0 && steps.every(s => isFinished(s.status)))) await putPlan($, { ...p, state: 'done', isFinishing: false })
      }
      isMainTurn = false
      if (owesDone) {
        owesDone = false
        play($, 'done')
      }
      // what the other sessions show: a reply ending in a question waits on the person; an interrupted turn shows nothing
      const isAsking = /[?？]\s*$/.test(e.answer ?? '')
      if (mine) mine.tool = ''
      await refreshTitle($)
      await publish($, e.reason !== 'answer' ? 'idle' : isAsking ? 'needs_input' : 'done')
    }

    return next(e)
  })
}

